import { writeFile } from "node:fs/promises";
import { join } from "node:path";

const args = process.argv.slice(2);

if (args.includes("--version")) {
  process.stdout.write(
    `${process.env.SKILLBENCH_FAKE_CLAUDE_MODE === "unsupported-version" ? "2.1.258" : "2.1.259"} (Claude Code)\n`,
  );
  process.exit(0);
}

if (!args.includes("-p")) {
  process.stderr.write("expected print mode\n");
  process.exit(2);
}

const mode = process.env.SKILLBENCH_FAKE_CLAUDE_MODE ?? "success";
if (mode === "timeout") {
  setInterval(() => undefined, 1_000);
  await new Promise(() => undefined);
}
if (mode === "nonzero") {
  process.stderr.write("fake claude failure\n");
  process.exit(7);
}
if (mode === "incompatible") {
  process.stdout.write("not-json\n");
  process.exit(0);
}

await writeFile(join(process.cwd(), "generated.txt"), "generated by fake Claude\n");
await writeFile(join(process.cwd(), "argv.json"), `${JSON.stringify(args)}\n`);
process.stdout.write(
  `${JSON.stringify({
    type: "result",
    subtype: "success",
    is_error: false,
    result: "FAKE_CLAUDE_OK",
    session_id: "fake-session",
    num_turns: 2,
    total_cost_usd: 0.001,
    usage: { input_tokens: 17, output_tokens: 6 },
  })}\n`,
);

if (mode === "large") process.stderr.write("x".repeat(16_384));
